// Lesson 4 - You're in Control (Mouse Group)
import coxprogramming.processing.sprites.*;

MyCharacter player;

void setup() {
  size(800, 600);
  player = new MyCharacter(this, width/2, height/2);
  player.setVelocity(4, 0);  // the speed followMouse() chases at
}

void draw() {
  background(240);
  player.followMouse();
  player.drawSprite();
}

void draw() {
  background(240);
  player.move();        // still needed - applies the velocity each frame
  player.drawSprite();
}

void keyPressed() {
  player.keyboardControl();   // arrow keys change the velocity
}

// Lesson 4 - You're in Control (Keys Group)
import coxprogramming.processing.sprites.*;

MyCharacter player;

void setup() {
  size(800, 600);
  player = new MyCharacter(this, width/2, height/2);
  player.setVelocity(4, 0);  // the drift before your first key
}

void draw() {
  background(240);
  player.move();        // still needed - applies the velocity each frame
  player.drawSprite();
}

// Arrow keys change the velocity
void keyPressed() {
  player.keyboardControl();
}
